interface OrderStore {
	executeSql(query: string, params: unknown[]): MySqlRow[];
}

class OrderService {
	constructor(private readonly store: OrderStore) {}

	pending(): number {
		const rows = this.store.executeSql("SELECT COUNT(*) AS n FROM orders WHERE status = ?", ["pending"]);
		return Number(rows[0]?.n ?? 0);
	}
}

